1: #!/usr/bin/env node
2: /**
3:  * zentao-resolve.mjs — 禅道 Bug 回写固定序列生成器
4:  *
5:  * 用途：把「开事务 → UPDATE zt_bug → INSERT zt_action → 复核 → commit」封成固定脚本，
6:  *       参数只暴露 bugId 和 comment，杜绝漏 connection_name / 列数不匹配等复发错误。
7:  *
8:  * 用法（推荐用文件/base64 传 comment，彻底避开 shell 引号地狱）：
9:  *   node zentao-resolve.mjs <bugId> --comment-file <path>      # 从 UTF-8 文件读 comment
10:  *   node zentao-resolve.mjs <bugId> --comment-b64 <base64>     # 从 base64 读（跨 shell 最安全）
11:  *   node zentao-resolve.mjs <bugId> <commentHTML>              # 兼容旧用法（短文本）
12:  * 输出：可直接照抄执行的 mcp_gateway 调用序列（JSON），以及各步的预期核验点。
13:  *
14:  * 约束（与 DBX.md 一致）：
15:  *   - 只对新禅道库（connection_name: "新禅道"）写；每次调用都必须带 connection_name。
16:  *   - zt_action 严格 14 列，files 用 NULL 占位；`read` 必须反引号。
17:  *   - comment 走 HTML，写根因 + 修复 + 验证证据。
18:  *   - 含 `'` / 换行 / HTML 的 comment 不要走位置参数（bug6402 亲历：单引号破坏
19:  *     PowerShell 单引号字符串 → ParserError），改用 --comment-file 或 --comment-b64。
20:  */
21: 
22: import { readFileSync } from "node:fs";
23: 
24: const argv = process.argv.slice(2);
25: const bugId = Number(argv[0]);
26: 
27: function flagValue(name) {
28:   const i = argv.indexOf(name);
29:   return i >= 0 && i + 1 < argv.length ? argv[i + 1] : undefined;
30: }
31: 
32: function loadComment() {
33:   const trimEol = (s) => s.replace(/[\r\n]+$/, "");
34:   const file = flagValue("--comment-file");
35:   if (file) return trimEol(readFileSync(file, "utf8"));
36:   const b64 = flagValue("--comment-b64");
37:   if (b64) return trimEol(Buffer.from(b64, "base64").toString("utf8"));
38:   // 兼容旧位置参数：跳过已消费的 flag 对，取第一个非 flag 参数
39:   for (let i = 1; i < argv.length; i++) {
40:     if (argv[i] === "--comment-file" || argv[i] === "--comment-b64") { i++; continue; }
41:     if (!argv[i].startsWith("--")) return argv[i];
42:   }
43:   return "";
44: }
45: 
46: const comment = loadComment();
47: 
48: if (!Number.isInteger(bugId) || bugId <= 0) {
49:   console.error("用法: node zentao-resolve.mjs <bugId> [--comment-file <path> | --comment-b64 <base64> | <commentHTML>]（bugId 必须为正整数）");
50:   process.exit(1);
51: }
52: if (!comment.trim()) {
53:   console.error("comment 不能为空：需要根因 + 修复 + 验证证据（HTML）");
54:   process.exit(1);
55: }
56: 
57: const CONN = "新禅道";
58: const ACTOR = "tiany";
59: const esc = (s) => s.replace(/'/g, "''");
60: 
61: const steps = [
62:   {
63:     name: "1) 查现状（拿 product/project/execution/openedBy）",
64:     sql:
65:       `SELECT id,status,assignedTo,openedBy,product,project,execution,resolution ` +
66:       `FROM zt_bug WHERE id=${bugId};`,
67:     verify: "记录 openedBy（回写 assignedTo 用）与 product/project/execution 原值",
68:   },
69:   {
70:     name: "2) 开事务 session",
71:     call: {
72:       server: "dbx",
73:       tool: "dbx_open_session",
74:       arguments: { connection_name: CONN, enable_transactions: true },
75:     },
76:     verify: "取返回的 session_id，后续所有事务内调用都带它 + connection_name",
77:   },
78:   {
79:     name: "3) begin",
80:     call: {
81:       server: "dbx",
82:       tool: "dbx_begin_transaction",
83:       arguments: { connection_name: CONN, session_id: "<session_id>" },
84:     },
85:     verify: "成功后再执行第 4/5 步",
86:   },
87:   {
88:     name: "4) UPDATE zt_bug → resolved",
89:     sql:
90:       `UPDATE zt_bug SET status='resolved', resolution='fixed', resolvedBuild='trunk', ` +
91:       `resolvedBy='${ACTOR}', resolvedDate=NOW(), assignedTo='<openedBy>', ` +
92:       `lastEditedBy='${ACTOR}', lastEditedDate=NOW() WHERE id=${bugId};`,
93:     verify: "affected rows = 1",
94:   },
95:   {
96:     name: "5) INSERT zt_action（14 列，files=NULL 占位）",
97:     sql:
98:       `INSERT INTO zt_action ` +
99:       `(objectType,objectID,product,project,execution,actor,action,date,comment,files,extra,\`read\`,efforted,vision) ` +
100:       `VALUES ('bug',${bugId},'<product>','<project>','<execution>','${ACTOR}','resolved',NOW(),` +
101:       `'${esc(comment)}',NULL,'fixed',0,0,'rnd');`,
102:     verify: "affected rows = 1；product/project/execution 用第 1 步查到的原值",
103:   },
104:   {
105:     name: "6) 事务内复核",
106:     sql:
107:       `SELECT status,resolution,resolvedBy,resolvedDate,assignedTo FROM zt_bug WHERE id=${bugId};\n` +
108:       `SELECT actor,action FROM zt_action WHERE objectType='bug' AND objectID=${bugId} ORDER BY id DESC;`,
109:     verify: "status=resolved / resolution=fixed / resolvedBy / assignedTo 均符合预期",
110:   },
111:   {
112:     name: "7) commit",
113:     call: {
114:       server: "dbx",
115:       tool: "dbx_commit_transaction",
116:       arguments: { connection_name: CONN, session_id: "<session_id>" },
117:     },
118:     verify: "返回 committed 即成功；不再做无 session 的第二次复核",
119:   },
120:   {
121:     name: "8) 关 session",
122:     call: {
123:       server: "dbx",
124:       tool: "dbx_close_session",
125:       arguments: { connection_name: CONN, session_id: "<session_id>" },
126:     },
127:     verify: "结束",
128:   },
129: ];
130: 
131: console.log(`# zt_bug ${bugId} 回写序列（connection_name=${CONN}，每步必带）\n`);
132: for (const s of steps) {
133:   console.log(`## ${s.name}`);
134:   if (s.call) {
135:     console.log("mcp_gateway " + JSON.stringify(s.call, null, 2));
136:   } else {
137:     const inTxn = /^[4-6]\)/.test(s.name);
138:     const arguments_ = { connection_name: CONN, sql: s.sql };
139:     if (inTxn) arguments_.session_id = "<session_id>";
140:     console.log(
141:       "mcp_gateway " +
142:         JSON.stringify(
143:           { server: "dbx", tool: "dbx_execute_query", arguments: arguments_ },
144:           null,
145:           2
146:         )
147:     );
148:   }
149:   console.log(`核验: ${s.verify}\n`);
150: }

